'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(!reduced){document.body.classList.add('motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});$$('.reveal').forEach(e=>observer.observe(e))}
const menu=$('.menu-toggle');menu.addEventListener('click',()=>{const open=$('nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});$$('nav a').forEach(a=>a.addEventListener('click',()=>{ $('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')}));
const categories={gasoline:'Gasoline engine oils',diesel:'Diesel engine oils',motorcycle:'Motorcycle oils',marine:'Marine oils',industrial:'Industrial oils',automatic_transmission:'Automatic transmission fluids',automatic_manual_gear:'Manual gear oils',brake:'Brake fluids',coolants:'Coolants & anti-freeze',greases:'Greases',additives:'Additives & car care'};
const officialPaths={gasoline:'GasolineEngineOils',diesel:'DieselEngineOils',motorcycle:'MotorcycleOils',marine:'MarineOils',industrial:'IndustrialOils/products-list.php',automatic_transmission:'AutomaticTransmissionFluids',automatic_manual_gear:'AutomotiveManualGearOils',brake:'BrakeFluids',coolants:'CoolantsAndAntiFreeze',greases:'Greases',additives:'AdditivesAndCarCare'};
const cat=$('#catalog'), detail=$('#product-detail');let catalogData=[];
$('#filter').innerHTML='<option value="all">All products</option><option value="automotive">All automotive</option>'+Object.entries(categories).map(([v,n])=>`<option value="${v}">${n}</option>`).join('');
$('#category-list').innerHTML=Object.entries(categories).map(([v,n])=>`<button data-filter="${v}">${n}<span>↗</span></button>`).join('');
function closeModal(d){d.close();if(!cat.open&&!detail.open)document.body.style.overflow=''}
$$('.close-dialog').forEach(b=>b.addEventListener('click',()=>closeModal(b.closest('dialog'))));[cat,detail].forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal(d)}});d.addEventListener('close',()=>{if(!cat.open&&!detail.open)document.body.style.overflow=''})});
function openCatalog(filter='all'){ $('#filter').value=filter;$('#search').value='';renderCatalog();if(!cat.open)cat.showModal();document.body.style.overflow='hidden'}
$('#open-catalog').addEventListener('click',()=>openCatalog());$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>openCatalog(b.dataset.filter)));
function productDetails(p){const box=$('#detail-content');box.replaceChildren();const img=document.createElement('img');img.src=p.image;img.alt=p.name;const copy=document.createElement('div');const type=document.createElement('span');type.className='eyebrow';type.textContent=categories[p.category];const h=document.createElement('h2');h.textContent=p.name;const desc=document.createElement('p');desc.textContent='Explore the official Petrovöll catalogue for available grades, packaging, performance specifications and application guidance.';const link=document.createElement('a');link.className='button';link.href='https://petrovoll.com/Products';link.target='_blank';link.rel='noopener';link.textContent='Official specifications ↗';const inquiry=document.createElement('a');inquiry.className='text-link';inquiry.href='mailto:info@petrovoll.com?subject='+encodeURIComponent('Product inquiry: '+p.name);inquiry.textContent='Ask about this product ↗';copy.append(type,h,desc,link,inquiry);box.append(img,copy);if(!detail.open)detail.showModal();document.body.style.overflow='hidden'}
function renderCatalog(){const filter=$('#filter').value,q=$('#search').value.toLowerCase();const rows=catalogData.filter(p=>(filter==='all'||p.category===filter||(filter==='automotive'&&!['marine','industrial','greases'].includes(p.category)))&&(p.name+' '+categories[p.category]).toLowerCase().includes(q));$('#result-count').textContent=rows.length+' products';const grid=$('#catalog-grid');grid.replaceChildren();rows.forEach(p=>{const b=document.createElement('button');b.className='catalog-product';const img=document.createElement('img');img.src=p.image;img.loading='lazy';img.alt=p.name;const h=document.createElement('h3');h.textContent=p.name;const c=document.createElement('span');c.textContent=categories[p.category].toUpperCase()+' ↗';b.append(img,h,c);b.addEventListener('click',()=>productDetails(p));grid.append(b)});if(!rows.length)grid.textContent='No matching products. Try another search.'}
$('#search').addEventListener('input',renderCatalog);$('#filter').addEventListener('change',renderCatalog);
fetch('catalog.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{catalogData=data;renderCatalog()}).catch(()=>{$('#result-count').textContent='The catalogue could not load. Please refresh or view the official product catalogue.';const a=document.createElement('a');a.href='https://petrovoll.com/Products';a.textContent='View official catalogue ↗';$('#catalog-grid').append(a)});
const stories=[{name:'STÄRK',category:'GASOLINE ENGINE OILS',title:'Power.<br><em>Beautifully<br>refined.</em>',desc:'Meet STÄRK. Fully synthetic gasoline engine oil for a new standard of everyday performance.',image:'assets/stark-render.webp',filter:'gasoline',note:'FULLY SYNTHETIC<br>GASOLINE ENGINE OIL'},{name:'VIRÖ-TEC',category:'DIESEL ENGINE OILS',title:'Demand more.<br><em>Keep moving.</em>',desc:'Explore the VIRÖ-TEC diesel engine oil family. Formulations for the engines that do the heavy lifting.',image:'assets/viro-transparent.webp',filter:'diesel',note:'DIESEL ENGINE OIL<br>VIRÖ-TEC FAMILY'},{name:'HYDKÖN',category:'INDUSTRIAL OILS',title:'Precision.<br><em>Under<br>pressure.</em>',desc:'Discover HYDKÖN hydraulic oil. Part of a complete industrial range for the machinery behind progress.',image:'assets/hydkon-transparent.webp',filter:'industrial',note:'HYDRAULIC OIL<br>INDUSTRIAL APPLICATIONS'}];
let currentStory=0;function showStory(i){if(i===currentStory)return;currentStory=i;const s=stories[i];$('#story-category').textContent=s.category;$('#story-title').innerHTML=s.title;$('#story-description').textContent=s.desc;$('.story-word').textContent=s.name;$('#product-note-text').innerHTML=s.note;$('#story-button').innerHTML='Explore '+s.name+' <span>↗</span>';const img=$('#showcase');img.src=s.image;img.alt='Petrovöll '+s.name+' lubricant packaging';img.classList.toggle('original',i!==0);$$('[data-story]').forEach((b,n)=>b.classList.toggle('active',i===n))}
$('#story-button').addEventListener('click',()=>openCatalog(stories[currentStory].filter));$$('[data-story]').forEach((b,i)=>b.addEventListener('click',()=>{if(reduced){showStory(i);return}const r=$('.product-story').getBoundingClientRect();const top=r.top+scrollY,total=r.height-innerHeight;window.scrollTo({top:top+total*(i+.2)/3,behavior:'smooth'})}));
const hero=$('.hero-sequence'),story=$('.product-story'),heroImage=$('.hero-image'),showcase=$('#showcase');
let scheduled=false;function updateScroll(){scheduled=false;const y=scrollY;$('.progress').style.width=(y/Math.max(1,document.documentElement.scrollHeight-innerHeight)*100)+'%'}
addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateScroll)}},{passive:true});updateScroll();
$$('[data-inquiry]').forEach(a=>a.addEventListener('click',()=>$('#inquiry').value=a.dataset.inquiry));$('#contact-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const subject=data.get('subject');const body='Name: '+data.get('name')+'\nEmail: '+data.get('email')+'\n\n'+data.get('message');location.href='mailto:info@petrovoll.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)});$('#year').textContent=new Date().getFullYear();
